    ll *w = (ll *)malloc((N + 1) * sizeof(ll));
    ll *t = (ll *)malloc((N + 1) * sizeof(ll));
    ll *W = (ll *)malloc((M + 1) * sizeof(ll));
    ll *T = (ll *)malloc((M + 1) * sizeof(ll));

    for (int i = 1; i <= N; i++) scanf("%lld %lld", &w[i], &t[i]);
    for (int i = 1; i <= M; i++) scanf("%lld %lld", &W[i], &T[i]);

    ll *pw = (ll *)malloc((N + 1) * sizeof(ll));
    ll *pt = (ll *)malloc((N + 1) * sizeof(ll));
    pw[0] = pt[0] = 0;
    for (int i = 1; i <= N; i++) {
        pw[i] = pw[i - 1] + w[i];
        pt[i] = pt[i - 1] + t[i];
    }

    int *left = (int *)malloc((M + 1) * sizeof(int));
    int r = 0;
    for (int i = 1; i <= M; i++) {
        if (r < i - 1) r = i - 1;
        while (r + 1 <= N) {
            ll sw = pw[r + 1] - pw[i - 1];
            ll st = pt[r + 1] - pt[i - 1];
            if (sw <= W[i] && st <= T[i]) r++;
            else break;
        }
        left[i] = r;
    }

    int *dp = (int *)malloc((M + 1) * sizeof(int));
    dp[0] = 0;
    for (int i = 1; i <= M; i++) dp[i] = dp[i - 1];

    for (int i = 1; i <= M; i++) {
        if (dp[i - 1] >= i - 1) {
            int reach = left[i];
            if (reach > dp[i]) dp[i] = reach;
        }
        if (dp[i] > dp[i - 1]) {
            for (int j = i + 1; j <= M && dp[j] < dp[i]; j++) {
                dp[j] = dp[i];
            }
        }
    }

    printf("%d\n", dp[M]);

    free(w);
    free(t);
    free(W);
    free(T);
    free(pw);
    free(pt);
    free(left);
    free(dp);
    return 0;
}

