    int maxWeight = 100000; // safe upper bound: N * max w[i] = 100*1000 = 100000
    const int INF = 1e9;
    vector<int> dp(maxWeight + 1, INF);
    dp[0] = 0;

    int totalWeight = 0;
    for (int i = 1; i <= N; ++i) totalWeight += w[i];

    // For each shelf, we do a knapsack on weight, keeping minimal thickness
    for (int shelf = 1; shelf <= M; ++shelf) {
