                    curW += w[k];
                    curT += t[k];
                    cnt++;
                } else break;
            }
            nextShelf[i][start] = cnt;
        }
    }

    // dp[i][pos] = max volumes arranged using first i shelves, ending at volume pos (inclusive)
    // We'll use 1-indexed for shelves and positions.
    vector<vector<int>> dp(M + 1, vector<int>(N + 1, -1));
    dp[0][0] = 0; // 0 shelves, 0 volumes arranged

    int answer = 0;
    for (int i = 1; i <= M; ++i) {
        for (int pos = 0; pos <= N; ++pos) {
            if (dp[i-1][pos] == -1) continue;
            // Option: don't use this shelf
            dp[i][pos] = max(dp[i][pos], dp[i-1][pos]);
            // Option: use this shelf starting from pos+1
            if (pos < N) {
                int take = nextShelf[i][pos+1];
                if (take > 0) {
                    int newPos = pos + take;
                    dp[i][newPos] = max(dp[i][newPos], dp[i-1][pos] + take);
                    answer = max(answer, dp[i][newPos]);
                }
            }
        }
    }

