import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        // Read number of shelves
        int N = Integer.parseInt(br.readLine());

        // Read shelf limits
        int[] widthLimit = new int[N];
        int[] weightLimit = new int[N];
        for (int i = 0; i < N; i++) {
            st = new StringTokenizer(br.readLine());
            widthLimit[i] = Integer.parseInt(st.nextToken());
            weightLimit[i] = Integer.parseInt(st.nextToken());
        }

        // Read number of books
        int M = Integer.parseInt(br.readLine());

        // Read book dimensions
        int[] thickness = new int[M];
        int[] weight = new int[M];
        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            thickness[i] = Integer.parseInt(st.nextToken());
            weight[i] = Integer.parseInt(st.nextToken());
        }

        // dp[i][w] = minimum thickness needed to arrange first i books with total weight w
        // We use a large value for impossible states
        int maxWeight = 0;
        for (int w : weightLimit) maxWeight += w;

        int[][] dp = new int[M + 1][maxWeight + 1];
        for (int[] row : dp) Arrays.fill(row, Integer.MAX_VALUE / 2);
        dp[0][0] = 0;

        for (int i = 1; i <= M; i++) {
            for (int w = 0; w <= maxWeight; w++) {
                // Don't take this book
                if (dp[i-1][w] < Integer.MAX_VALUE / 2) {
                    dp[i][w] = Math.min(dp[i][w], dp[i-1][w]);
                }
                // Take this book
                if (w >= weight[i-1]) {
                    int prevThickness = dp[i-1][w - weight[i-1]];
                    if (prevThickness < Integer.MAX_VALUE / 2) {
                        dp[i][w] = Math.min(dp[i][w], prevThickness + thickness[i-1]);
                    }
                }
            }
        }

        // Now we need to check if we can arrange books 1..k on shelves
        // We'll binary search on k
        int left = 0, right = M;
        while (left < right) {
            int mid = (left + right + 1) / 2;
            if (canArrange(mid, dp, widthLimit, weightLimit, maxWeight)) {
                left = mid;
            } else {
                right = mid - 1;
            }
        }

        System.out.println(left);
    }

    private static boolean canArrange(int k, int[][] dp, int[] widthLimit, int[] weightLimit, int maxWeight) {
        // Check all possible total weights for first k books
        for (int totalWeight = 0; totalWeight <= maxWeight; totalWeight++) {
            if (dp[k][totalWeight] < Integer.MAX_VALUE / 2) {
                int totalThickness = dp[k][totalWeight];
                // Can we fit this total weight and thickness into the shelves?
                if (canFit(totalWeight, totalThickness, widthLimit, weightLimit)) {
                    return true;
                }
            }
        }
        return false;
    }

    private static boolean canFit(int totalWeight, int totalThickness, int[] widthLimit, int[] weightLimit) {
        int N = widthLimit.length;
        // Use DP to see if we can partition weight and thickness into shelves
        // dp2[mask] = minimum thickness achievable for given weight using subset of shelves
        int totalShelves = N;
        int[] dp2 = new int[1 << totalShelves];
        Arrays.fill(dp2, Integer.MAX_VALUE / 2);
        dp2[0] = 0;

        for (int mask = 0; mask < (1 << totalShelves); mask++) {
            if (dp2[mask] > totalThickness) continue;
            int usedWeight = 0;
            int usedThickness = 0;
            for (int i = 0; i < totalShelves; i++) {
                if ((mask & (1 << i)) != 0) {
                    usedWeight += weightLimit[i];
                    usedThickness += widthLimit[i];
                }
            }
            if (usedWeight >= totalWeight && usedThickness >= totalThickness) {
                return true;
            }
        }
        return false;
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int N = fs.nextInt(); // number of volumes
        int M = fs.nextInt(); // number of shelves

        long[] width = new long[M + 1];
        long[] weightLimit = new long[M + 1];
        for (int i = 1; i <= M; i++) {
            width[i] = fs.nextLong();
            weightLimit[i] = fs.nextLong();
        }

        long[] thick = new long[N + 1];
        long[] weight = new long[N + 1];
        for (int i = 1; i <= N; i++) {
            thick[i] = fs.nextLong();
            weight[i] = fs.nextLong();
        }

        long[] prefThick = new long[N + 1];
        long[] prefWeight = new long[N + 1];
        for (int i = 1; i <= N; i++) {
            prefThick[i] = prefThick[i - 1] + thick[i];
            prefWeight[i] = prefWeight[i - 1] + weight[i];
        }

        int[] dp = new int[M + 1];
        for (int i = 0; i <= M; i++) dp[i] = -1;
        dp[0] = 0;

        for (int i = 1; i <= M; i++) {
            dp[i] = dp[i - 1]; // can always ignore this shelf
            for (int j = 0; j < i; j++) {
                if (dp[j] < 0) continue;
                int start = dp[j] + 1;
                int lo = start, hi = N, best = dp[j];

                while (lo <= hi) {
                    int mid = (lo + hi) >>> 1;
                    long sumThick = prefThick[mid] - prefThick[start - 1];
                    long sumWeight = prefWeight[mid] - prefWeight[start - 1];
                    if (sumThick <= width[i] && sumWeight <= weightLimit[i]) {
                        best = mid;
                        lo = mid + 1;
                    } else {
                        hi = mid - 1;
                    }
                }
                dp[i] = Math.max(dp[i], best);
            }
        }

        System.out.println(dp[M]);
    }
}
